-- Migration 011: Add rank_bucket to rune_ctx (D-022 expertWeight, SPECS §3)
-- Rune contexts are now stored per user rank bucket so the export can serve
-- rank-specific evidence (games below the user bucket excluded, games above
-- boosted). The primary key changes, so the table is rebuilt. Existing rows
-- carry no bucket and are regenerated by the next `pnpm etl aggregate`.
DROP INDEX IF EXISTS idx_rune_ctx_champion;
DROP TABLE rune_ctx;

CREATE TABLE rune_ctx (
  champion_id INTEGER NOT NULL,
  my_role TEXT NOT NULL,
  rank_bucket TEXT NOT NULL,
  context_key TEXT NOT NULL,
  context_level INTEGER NOT NULL DEFAULT 1,
  perks_hash TEXT NOT NULL,
  perks_json TEXT NOT NULL,
  wins_w REAL NOT NULL,
  games_w REAL NOT NULL,
  games_w2 REAL NOT NULL,
  players INTEGER NOT NULL,
  PRIMARY KEY (champion_id, my_role, rank_bucket, context_key, perks_hash)
);

CREATE INDEX idx_rune_ctx_champion ON rune_ctx (champion_id, my_role);
